### cot
1. Validate that the URL and filename are non-empty strings.
2. Create the download directory if it does not exist.
3. Download the zip file from the URL and save it to the download directory.
4. Create the extraction directory if it does not exist.
5. Open the downloaded zip file and extract all contents to the extraction directory.
6. List the filenames in the extraction directory.
7. Return a tuple with a success status message and the list of filenames.
8. Handle network errors by returning an error status message and an empty list.
9. Handle file extraction errors by returning an error status message and an empty list.

### code
```python
import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    try:
        if not url or not filename:
            return ("Error: URL and filename must be non-empty.", [])

        DOWNLOAD_DIR.mkdir(exist_ok=True)
        ZIP_DIR.mkdir(exist_ok=True)

        zip_path = DOWNLOAD_DIR / filename
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()

        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        try:
            with zipfile.ZipFile(zip_path, 'r') as zip_ref:
                zip_ref.extractall(ZIP_DIR)
        except (zipfile.BadZipFile, OSError) as e:
            return (f"Error: File extraction failed - {e}", [])

        filenames = [f.name for f in ZIP_DIR.iterdir() if f.is_file()]
        return ("Success", filenames)

    except requests.RequestException as e:
        return (f"Error: Download failed - {e}", [])
    except OSError as e:
        return (f"Error: File handling error - {e}", [])
